import{c as t,Q as e,j as n,m as s}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"SetMatmulConfigParams","description":"","frontmatter":{},"headers":[{"level":1,"title":"SetMatmulConfigParams","slug":"setmatmulconfigparams"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetMatmulConfigParams.md","filePath":"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetMatmulConfigParams.md"}'),l={name:"api/SIMD-API/高阶API/矩阵计算/Matmul-Tiling侧接口/Matmul-Tiling类/SetMatmulConfigParams.md"};function i(p,a,r,o,d,m){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="setmatmulconfigparams" tabindex="-1">SetMatmulConfigParams <a class="header-anchor" href="#setmatmulconfigparams" aria-label="Permalink to &quot;SetMatmulConfigParams&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>在计算Tiling时，用于自定义设置<a href="#table9646134355611">表1</a>中的MatmulConfig参数。本接口中配置的参数对应的功能在Tiling与Kernel中需要保持一致，所以本接口中的参数取值，需要与Kernel侧对应的MatmulConfig参数值保持一致，详细MatmulConfig参数请见<a href="./MatmulConfig.html#table1761013213153">表2</a>。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void SetMatmulConfigParams(int32_t mmConfigTypeIn = 1, bool enableL1CacheUBIn = false, ScheduleType scheduleTypeIn = ScheduleType::INNER_PRODUCT, MatrixTraverse traverseIn = MatrixTraverse::NOSET, bool enVecND2NZIn = false)</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void SetMatmulConfigParams(const MatmulConfigParams&amp; configParams)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>mmConfigTypeIn</td><td>输入</td><td>设置Matmul的模板类型，需要与Matmul对象创建的模板一致，当前只支持配置为0或1。 0：代表Norm模板1：代表MDL模板，默认值为1</td></tr><tr><td>enableL1CacheUBIn</td><td>输入</td><td>配置是否使能L1缓存UB计算块；参考使能场景：MTE3和MTE2流水串行较多的场景。 false：不使能L1缓存UB计算块，默认值为falsetrue：使能L1缓存UB计算块 Atlas A3 训练系列产品/Atlas A3 推理系列产品不支持该参数。 Atlas A2 训练系列产品/Atlas A2 推理系列产品不支持该参数。 Atlas 推理系列产品AI Core支持该参数。 Atlas 200I/500 A2 推理产品不支持该参数。</td></tr><tr><td>scheduleTypeIn</td><td>输入</td><td>配置Matmul数据搬运模式。参数取值如下： ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运ScheduleType::N_BUFFER_33：NBuffer33模板的数据搬运模式，MTE2每次搬运A矩阵的1x3个基本块，直至A矩阵所有3x3个基本块全载在L1 Buffer中</td></tr><tr><td>traverseIn</td><td>输入</td><td>Matmul做矩阵运算的循环迭代顺序，即一次迭代计算出[baseM, baseN]大小的C矩阵分片后，自动偏移到下一次迭代输出的C矩阵位置的偏移顺序。参数取值如下： NOSET：0，当前无效。 FIRSTM：先往M轴方向偏移再往N轴方向偏移。 FIRSTN：先往N轴方向偏移再往M轴方向偏移。</td></tr><tr><td>enVecND2NZIn</td><td>输入</td><td>是否使能ND2NZ。</td></tr><tr><td>configParams</td><td>输入</td><td>config相关参数，类型为MatmulConfigParams，结构体具体定义如下方代码所示。其中的参数说明请参考表2。</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>struct MatmulConfigParams</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int32_t mmConfigType;</span></span>
<span class="line"><span>    bool enableL1CacheUB;</span></span>
<span class="line"><span>    ScheduleType scheduleType;</span></span>
<span class="line"><span>    MatrixTraverse traverse;</span></span>
<span class="line"><span>    bool enVecND2NZ;</span></span>
<span class="line"><span>    MatmulConfigParams(int32_t mmConfigTypeIn = 1, bool enableL1CacheUBIn = false,</span></span>
<span class="line"><span>        ScheduleType scheduleTypeIn = ScheduleType::INNER_PRODUCT, MatrixTraverse traverseIn = MatrixTraverse::NOSET,</span></span>
<span class="line"><span>        bool enVecND2NZIn = false) {</span></span>
<span class="line"><span>        mmConfigType = mmConfigTypeIn;</span></span>
<span class="line"><span>        enableL1CacheUB = enableL1CacheUBIn;</span></span>
<span class="line"><span>        scheduleType = scheduleTypeIn;</span></span>
<span class="line"><span>        traverse = traverseIn;</span></span>
<span class="line"><span>        enVecND2NZ = enVecND2NZIn;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>};</span></span></code></pre></div><p><strong>表 2</strong> MatmulConfigParams结构体内参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>mmConfigType</td><td>设置Matmul的模板类型，需要与Matmul对象创建的模板一致，当前只支持配置为0或1。 0：代表Norm模板1：代表MDL模板，默认值为1</td></tr><tr><td>enableL1CacheUB</td><td>配置是否使能L1缓存UB计算块；参考使能场景：MTE3和MTE2流水串行较多的场景。 false：不使能L1缓存UB计算块，默认值为falsetrue：使能L1缓存UB计算块</td></tr><tr><td>scheduleType</td><td>配置Matmul数据搬运模式。参数取值如下： ScheduleType::INNER_PRODUCT：默认模式，在K方向上做MTE1的循环搬运ScheduleType::OUTER_PRODUCT：在M或N方向上做MTE1的循环搬运ScheduleType::N_BUFFER_33：NBuffer33模板的数据搬运模式，MTE2每次搬运A矩阵的1x3个基本块，直至A矩阵所有3x3个基本块全载在L1 Buffer中</td></tr><tr><td>traverse</td><td>Matmul做矩阵运算的循环迭代顺序，即一次迭代计算出[baseM, baseN]大小的C矩阵分片后，自动偏移到下一次迭代输出的C矩阵位置的偏移顺序。参数取值如下： NOSET：0，当前无效。 FIRSTM：先往M轴方向偏移再往N轴方向偏移。 FIRSTN：先往N轴方向偏移再往M轴方向偏移。</td></tr><tr><td>enVecND2NZ</td><td>是否使能ND2NZ</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>本接口必须在<a href="./GetTiling.html">GetTiling</a>接口前调用。</li><li>若Matmul对象使用NBuffer33模板策略，即MatmulPolicy为<a href="./../../Matmul-Kernel侧接口/MatmulPolicy.html#li194081238103913">NBuffer33MatmulPolicy</a>，则在调用<a href="./GetTiling.html">GetTiling</a>接口生成Tiling参数前，必须通过本接口将scheduleTypeIn参数设置为ScheduleType::N_BUFFER_33，以启用NBuffer33模板策略的Tiling生成逻辑。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>auto ascendcPlatform = platform_ascendc::PlatformAscendC(context-&gt;GetPlatformInfo());</span></span>
<span class="line"><span>matmul_tiling::MatmulApiTiling tiling(ascendcPlatform); </span></span>
<span class="line"><span>tiling.SetAType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16); </span></span>
<span class="line"><span>tiling.SetBType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT16);   </span></span>
<span class="line"><span>tiling.SetCType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetBiasType(matmul_tiling::TPosition::GM, matmul_tiling::CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);   </span></span>
<span class="line"><span>tiling.SetShape(1024, 1024, 1024);   </span></span>
<span class="line"><span>tiling.SetOrgShape(1024, 1024, 1024);  </span></span>
<span class="line"><span>tiling.SetBias(true);   </span></span>
<span class="line"><span>tiling.SetBufferSpace(-1, -1, -1);</span></span>
<span class="line"><span>tiling.SetMatmulConfigParams(0);  // 额外设置</span></span>
<span class="line"><span>// matmul_tiling::MatmulConfigParams configParams = {1, false, matmul_tiling::ScheduleType::OUTER_PRODUCT, matmul_tiling::MatrixTraverse::FIRSTM};</span></span>
<span class="line"><span>// tiling.SetMatmulConfigParams(configParams);</span></span>
<span class="line"><span>optiling::TCubeTiling tilingData;   </span></span>
<span class="line"><span>int ret = tiling.GetTiling(tilingData);</span></span></code></pre></div>`,18)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
